from pathlib import Path
import base64, subprocess

ROOT = Path.cwd()
def fail(m): raise SystemExit('\nPATCH STOPPED: ' + m + '\n')
def read(rel):
    p=ROOT/rel
    if not p.exists(): fail('Missing expected file: '+rel)
    return p.read_text(encoding='utf-8')
def write(rel,s):
    p=ROOT/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(s,encoding='utf-8')
def rep(text,old,new,label):
    c=text.count(old)
    if c!=1: fail(f'{label}: expected exactly 1 match, found {c}')
    return text.replace(old,new,1)

